package com.fasterxml.jackson.databind.deser;

import com.fasterxml.jackson.annotation.JsonFormat;
import com.fasterxml.jackson.annotation.JsonIgnoreProperties;
import com.fasterxml.jackson.annotation.JsonProperty;
import com.fasterxml.jackson.annotation.JsonTypeInfo;
import com.fasterxml.jackson.annotation.ObjectIdGenerator;
import com.fasterxml.jackson.annotation.ObjectIdGenerators;
import com.fasterxml.jackson.annotation.ObjectIdResolver;
import com.fasterxml.jackson.core.*;
import com.fasterxml.jackson.core.JsonParser.NumberType;
import com.fasterxml.jackson.databind.*;
import com.fasterxml.jackson.databind.annotation.JsonDeserialize;
import com.fasterxml.jackson.databind.deser.BeanDeserializerBuilder;
import com.fasterxml.jackson.databind.deser.impl.*;
import com.fasterxml.jackson.databind.deser.std.StdDelegatingDeserializer;
import com.fasterxml.jackson.databind.deser.std.StdDeserializer;
import com.fasterxml.jackson.databind.exc.IgnoredPropertyException;
import com.fasterxml.jackson.databind.introspect.*;
import com.fasterxml.jackson.databind.jsontype.TypeDeserializer;
import com.fasterxml.jackson.databind.ser.BeanPropertyMap;
import com.fasterxml.jackson.databind.type.ClassKey;
import com.fasterxml.jackson.databind.util.*;
import java.io.*;
import java.io.IOException;
import java.lang.reflect.Constructor;
import java.lang.reflect.InvocationTargetException;
import java.math.*;
import java.util.*;
import org.junit.*;
import org.junit.Before;
import org.junit.Test;
import org.mockito.Mockito;
import static org.junit.Assert.*;
import static org.mockito.ArgumentMatchers.*;
import static org.mockito.Mockito.*;

public class BeanDeserializerBase_createContextual_TriageGen2Test {

    private DeserializationContext ctxt;
    private BeanProperty property;
    private AnnotationIntrospector intr;
    private BeanDescription beanDesc;
    private BeanDeserializerBuilder builder;
    private BeanPropertyMap beanProperties;

    // Concrete implementation of BeanDeserializerBase for testing
    private static class TestBeanDeserializer extends BeanDeserializer {
        private JsonFormat.Shape serializationShape;

        protected TestBeanDeserializer(BeanDeserializerBuilder builder, BeanDescription beanDesc, BeanPropertyMap properties, 
                                      Map<String, SettableBeanProperty> backRefs, Set<String> ignorableProps, 
                                      boolean ignoreAllUnknown, boolean hasViews) {
            super(builder, beanDesc, properties, backRefs, ignorableProps, ignoreAllUnknown, hasViews);
        }

        @Override
        protected BeanDeserializer asArrayDeserializer() {
            return new TestBeanDeserializer(this);
        }

        public void setSerializationShape(JsonFormat.Shape shape) {
            this.serializationShape = shape;
        }

        @Override
        public JsonDeserializer<Object> unwrappingDeserializer(NameTransformer unwrapper) { return this; }
    }

    @Before
    public void setUp() {
        ctxt = mock(DeserializationContext.class);
        property = mock(BeanProperty.class);
        intr = mock(AnnotationIntrospector.class);
        beanDesc = mock(BeanDescription.class);
        builder = mock(BeanDeserializerBuilder.class);
        beanProperties = mock(BeanPropertyMap.class);

        when(ctxt.getAnnotationIntrospector()).thenReturn(intr);
        when(beanDesc.constructType(any())).thenReturn(DataType.construct(Object.class));
        when(beanDesc.findProperties()).thenReturn(Collections.emptyList());
        when(beanDesc.findIdProperties()).thenReturn(Collections.emptyList());
    }

    private TestBeanDeserializer createDeserializer() {
        return new TestBeanDeserializer(builder, beanDesc, beanProperties, new HashMap<>(), new HashSet<>(), true, false);
    }

    @Test
    public void testCreateContextual_NullPropertyAndIntrospector() throws JsonMappingException {
        TestBeanDeserializer deser = createDeserializer();
        JsonDeserializer<?> result = deser.createContextual(ctxt, null);
        assertEquals(deser, result);
    }

    @Test
    public void testCreateContextual_NoObjectIdInfo() throws JsonMappingException {
        TestBeanDeserializer deser = createDeserializer();
        AnnotatedMember member = mock(AnnotatedMember.class);
        when(property.getMember()).thenReturn(member);
        when(intr.findObjectIdInfo(member)).thenReturn(null);

        JsonDeserializer<?> result = deser.createContextual(ctxt, property);
        assertEquals(deser, result);
    }

    @Test
    public void testCreateContextual_PropertyBasedObjectIdGenerator_Success() throws JsonMappingException {
        TestBeanDeserializer deser = createDeserializer();
        AnnotatedMember member = mock(AnnotatedMember.class);
        when(property.getMember()).thenReturn(member);
        when(intr.findObjectIdInfo(member)).thenReturn(mock(ObjectIdInfo.class));

        ObjectIdInfo objectIdInfo = mock(ObjectIdInfo.class);
        when(intr.findObjectIdInfo(member)).thenReturn(objectIdInfo);
        when(objectIdInfo.getGeneratorType()).thenReturn(ObjectIdGenerators.PropertyGenerator.class);
        when(objectIdInfo.getPropertyName()).thenReturn("id");
        when(objectIdInfo.getScope()).thenReturn("scope");
        when(intr.findObjectReferenceInfo(eq(member), any())).thenReturn(objectIdInfo);

        SettableBeanProperty idProp = mock(SettableBeanProperty.class);
        when(idProp.getType()).thenReturn(DataType.construct(String.class));

        // Use a spy to mock findProperty
        TestBeanDeserializer spyDeser = spy(deser);
        doReturn(idProp).when(spyDeser).findProperty("id");
        when(spyDeser.handledType()).thenReturn(Object.class);

        when(ctxt.objectIdResolverInstance(eq(member), eq(objectIdInfo))).thenReturn(mock(ObjectIdResolver.class));
        when(ctxt.constructType(String.class)).thenReturn(DataType.construct(String.class));
        when(ctxt.findRootValueDeserializer(any())).thenReturn(mock(JsonDeserializer.class));

        JsonDeserializer<?> result = spyDeser.createContextual(ctxt, property);
        assertNotNull(result);
        verify(spyDeser).withObjectIdReader(any());
    }

    @Test(expected = IllegalArgumentException.class)
    public void testCreateContextual_PropertyBasedObjectIdGenerator_Failure() throws JsonMappingException {
        TestBeanDeserializer deser = createDeserializer();
        AnnotatedMember member = mock(AnnotatedMember.class);
        when(property.getMember()).thenReturn(member);

        ObjectIdInfo objectIdInfo = mock(ObjectIdInfo.class);
        when(objectIdInfo.getGeneratorType()).thenReturn(ObjectIdGenerators.PropertyGenerator.class);
        when(objectIdInfo.getPropertyName()).thenReturn("missingProp");
        when(intr.findObjectIdInfo(member)).thenReturn(objectIdInfo);
        when(intr.findObjectReferenceInfo(eq(member), any())).thenReturn(objectIdInfo);
        when(deser.handledType()).thenReturn(Object.class);

        TestBeanDeserializer spyDeser = spy(deser);
        doReturn(null).when(spyDeser).findProperty("missingProp");

        spyDeser.createContextual(ctxt, property);
    }

    @Test
    public void testCreateContextual_OtherObjectIdGenerator() throws JsonMappingException {
        TestBeanDeserializer deser = createDeserializer();
        AnnotatedMember member = mock(AnnotatedMember.class);
        when(property.getMember()).thenReturn(member);

        ObjectIdInfo objectIdInfo = mock(ObjectIdInfo.class);
        when(objectIdInfo.getGeneratorType()).thenReturn(ObjectIdGenerators.GUIDGenerator.class);
        when(objectIdInfo.getPropertyName()).thenReturn("id");
        when(intr.findObjectIdInfo(member)).thenReturn(objectIdInfo);
        when(intr.findObjectReferenceInfo(eq(member), any())).thenReturn(objectIdInfo);

        when(deser.handledType()).thenReturn(Object.class);
        when(ctxt.constructType(any())).thenReturn(DataType.construct(String.class));
        when(ctxt.getTypeFactory().findTypeParameters(any(), any())).thenReturn(Collections.singletonList(DataType.construct(Object.class)));
        when(ctxt.objectIdGeneratorInstance(eq(member), eq(objectIdInfo))).thenReturn(mock(ObjectIdGenerator.class));
        when(ctxt.findRootValueDeserializer(any())).thenReturn(mock(JsonDeserializer.class));

        TestBeanDeserializer spyDeser = spy(deser);
        JsonDeserializer<?> result = spyDeser.createContextual(ctxt, property);
        assertNotNull(result);
    }

    @Test
    public void testCreateContextual_WithIgnorableProperties() throws JsonMappingException {
        TestBeanDeserializer deser = createDeserializer();
        AnnotatedMember member = mock(AnnotatedMember.class);
        when(property.getMember()).thenReturn(member);
        when(intr.findObjectIdInfo(member)).thenReturn(null);

        JsonIgnoreProperties.Value ignorals = mock(JsonIgnoreProperties.Value.class);
        when(intr.findPropertyIgnorals(member)).thenReturn(ignorals);
        when(ignorals.findIgnoredForDeserialization()).thenReturn(new HashSet<>(Arrays.asList("prop1")));

        TestBeanDeserializer spyDeser = spy(deser);
        // Setup existing ignorables in the original deserializer via constructor (simulated)
        // Since we can't easily trigger the internal _ignorableProps through public API, we rely on the logic

        JsonDeserializer<?> result = spyDeser.createContextual(ctxt, property);
        verify(spyDeser, atLeastOnce()).withIgnorableProperties(any());
    }

    @Test
    public void testCreateContextual_JsonFormatOverrides() throws JsonMappingException {
        TestBeanDeserializer deser = createDeserializer();
        AnnotatedMember member = mock(AnnotatedMember.class);
        when(property.getMember()).thenReturn(member);
        when(intr.findObjectIdInfo(member)).thenReturn(null);
        when(intr.findPropertyIgnorals(member)).thenReturn(null);

        // Mock JsonFormat
        JsonFormat.Value format = mock(JsonFormat.Value.class);
        when(format.hasShape()).thenReturn(true);
        when(format.getShape()).thenReturn(JsonFormat.Shape.ARRAY);
        when(format.getFeature(JsonFormat.Feature.ACCEPT_CASE_INSENSITIVE_PROPERTIES)).thenReturn(true);

        // We need to mock findFormatOverrides which is protected. 
        // In real Jackson, this calls intr.findFormatOverrides.
        when(intr.findFormatOverrides(any(), any())).thenReturn(format);

        // Mock beanProperties for case insensitivity
        BeanPropertyMap caseInsensitiveProps = mock(BeanPropertyMap.class);
        when(beanProperties.withCaseInsensitivity(true)).thenReturn(caseInsensitiveProps);

        TestBeanDeserializer spyDeser = spy(deser);
        doReturn(caseInsensitiveProps).when(beanProperties).withCaseInsensitivity(anyBoolean());
        // The code uses _beanProperties which is private, but we can simulate the effect via withBeanProperties

        // To test the shape logic:
        deser.setSerializationShape(JsonFormat.Shape.OBJECT);

        JsonDeserializer<?> result = spyDeser.createContextual(ctxt, property);

        // If shape is ARRAY, it should call asArrayDeserializer
        verify(spyDeser).asArrayDeserializer();
    }

    @Test
    public void testCreateContextual_CaseInsensitivityOnly() throws JsonMappingException {
        TestBeanDeserializer deser = createDeserializer();
        AnnotatedMember member = mock(AnnotatedMember.class);
        when(property.getMember()).thenReturn(member);
        when(intr.findObjectIdInfo(member)).thenReturn(null);
        when(intr.findPropertyIgnorals(member)).thenReturn(null);

        JsonFormat.Value format = mock(JsonFormat.Value.class);
        when(format.hasShape()).thenReturn(false);
        when(format.getFeature(JsonFormat.Feature.ACCEPT_CASE_INSENSITIVE_PROPERTIES)).thenReturn(true);
        when(intr.findFormatOverrides(any(), any())).thenReturn(format);

        BeanPropertyMap newProps = mock(BeanPropertyMap.class);
        when(beanProperties.withCaseInsensitivity(true)).thenReturn(newProps);

        TestBeanDeserializer spyDeser = spy(deser);
        spyDeser.createContextual(ctxt, property);

        verify(spyDeser).withBeanProperties(newProps);
    }
}
